// Read-only public GitHub metadata: PR #2 run 39363468169 and main run 39365372435 at 9081192. No log or artifact download.
const root = 'https://api.github.com/repos/chroniicallydiistracted/lorcana-online-tcg/actions/runs/';
async function get(path) {
  const r = await fetch(root + path, { headers: { Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' }, signal: AbortSignal.timeout(15000) });
  if (!r.ok) throw new Error('Public GitHub metadata unavailable: ' + r.status);
  return r.json();
}
const out = [];
for (const [id, attempt] of [[39363468169, 1], [39365372435, 1]]) {
  const v = await get(id + '/attempts/' + attempt), j = await get(id + '/attempts/' + attempt + '/jobs?per_page=100');
  if (v.id !== id || v.run_attempt !== attempt || v.head_sha !== '9081192dc77d5e8b3d4b10dfbfd975d910081811') throw new Error('Unexpected hosted metadata');
  out.push({ id, attempt, event: v.event, head_branch: v.head_branch, head_sha: v.head_sha, status: v.status, conclusion: v.conclusion, run_started_at: v.run_started_at, updated_at: v.updated_at,
    jobs: j.jobs.map(x => ({ name: x.name, conclusion: x.conclusion, started_at: x.started_at, completed_at: x.completed_at, steps: x.steps.map(s => s.name + ':' + s.conclusion) })) });
}
if (out.some(o => o.conclusion !== 'success' || o.jobs.some(j => j.conclusion !== 'success'))) throw new Error('Hosted results differ from the reviewer observation');
console.log(JSON.stringify(out));
